#pragma once
#include "VFX/VFXInternal.h"
#include "Bazzalt/AssetManager.h"
#include "Rendering/PrimitiveGeometry.h"
#include "Rendering/ModelGeometry.h"
#include <fstream>
namespace Bazzalt::Runtime {
inline std::vector<GraphicsVertex> ParticleMesh(const VFXProgram& p){
 std::vector<GraphicsVertex> vertices;
 if(!p.Mesh){PrimitiveObject primitive;primitive.Shape=static_cast<PrimitiveShape>(p.MeshPrimitive);primitive.Segments=8;primitive.Rings=6;auto geometry=GetCachedPrimitiveGeometry(primitive);for(std::size_t i=0;i<geometry->Indices.size();i+=3){Vec3 a,b,c;const auto point=[&](unsigned n){auto& v=geometry->Vertices[geometry->Indices[i+n]];return Vec3{v.Position[0],v.Position[1],v.Position[2]};};a=point(0);b=point(1);c=point(2);auto normal=Vec3::Cross(b-a,c-a).Normalized();if(normal.LengthSquared()<1e-12f)normal={0,1,0};for(unsigned n=0;n<3;++n){auto& v=geometry->Vertices[geometry->Indices[i+n]];vertices.push_back({point(n),normal,{v.UV[0],v.UV[1]},{1,1,1,1}});}}return vertices;}
 auto asset=AssetManager::GetAsset(p.Mesh);if(!asset||asset->State!=AssetState::Ready)throw std::invalid_argument("Particle mesh asset is unavailable");std::ifstream file(asset->CachePath,std::ios::binary|std::ios::ate);auto size=file.tellg();if(size<=0||size>64*1024*1024)throw std::invalid_argument("Particle mesh exceeds 64 MiB");std::vector<std::uint8_t> bytes(std::size_t(size),0);file.seekg(0);if(!file.read(reinterpret_cast<char*>(bytes.data()),size))throw std::invalid_argument("Cannot read particle mesh");auto geometry=ReadModelGeometry(bytes,asset->CachePath);auto model=AssetManager::LoadModel(p.Mesh);if(!geometry||!model)throw std::invalid_argument("Particle mesh requires an imported glTF model");
 const auto walk=[&](auto&& self,unsigned index,const Mat4& parent,unsigned depth)->void{if(depth>128||index>=model->Nodes.size())throw std::invalid_argument("Invalid particle mesh hierarchy");const auto& node=model->Nodes[index];auto world=parent*Mat4::Transform(node.Position,node.Rotation,node.Scale);if(node.HasMesh()&&(p.MeshNode<0||node.SourceIndex==unsigned(p.MeshNode))&&node.SourceIndex<geometry->SourceNodes.size()){auto source=geometry->SourceNodes[node.SourceIndex];if(source){if(vertices.size()+source->Triangles.size()*3>6144)throw std::invalid_argument("Particle mesh exceeds 2048 triangles; use a lower LOD or a source node");auto normals=world.Inversed().Transposed();for(const auto& t:source->Triangles){auto normal=Vec3::Cross(t.B-t.A,t.C-t.A).Normalized();std::array<Vec3,3> pos{t.A,t.B,t.C},n{t.NA,t.NB,t.NC};std::array<Vec2,3> uv{t.UVA,t.UVB,t.UVC};for(unsigned i=0;i<3;++i){auto out=normals.TransformDirection(n[i].LengthSquared()>1e-12f?n[i]:normal).Normalized();if(out.LengthSquared()<1e-12f)out={0,1,0};vertices.push_back({world.TransformPoint(pos[i]),out,uv[i],{1,1,1,1}});}}}}for(auto child:node.Children)self(self,child,world,depth+1);};for(auto root:model->Roots)walk(walk,root,{},0);if(vertices.empty())throw std::invalid_argument("Particle mesh node has no triangles");return vertices;
}
}
